import './Main.css';
import Bar from './Bar.js'
import Question from './Question.js'
import { useState } from 'react';
function Main () {
    const [isMemorising, setIsMemorising] = useState(true);

    return (
        <div className='main'>
            <Question length = {20}/>
            <div className = "second_layer">
                <Bar isMemorising = {isMemorising} />
                <button className='button' onClick={setIsMemorising(() => false)}> Start </button>
            </div>
        </div>
    )
}

export default Main;
